import{z as i,x as B,o,c as p,q as t,j as l,D as e,d as E,s as n,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"索引选择与条件下推","description":"","frontmatter":{"title":"索引选择与条件下推","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/index-selection.md","filePath":"cs/index-selection.md","lastUpdated":1791413859000}'),c={name:"cs/index-selection.md"};function A(h,a,D,m,u,f){const s=B("Mermaid");return o(),p("div",null,[a[2]||(a[2]=t('<h1 id="索引选择与条件下推" tabindex="-1">索引选择与条件下推 <a class="header-anchor" href="#索引选择与条件下推" aria-label="Permalink to &quot;索引选择与条件下推&quot;">​</a></h1><div class="epigraph"><p>索引是物理设计的赌注：哪些谓词值得变成有序或哈希访问。条件下推把谓词贴到扫描上，否则索引建了也用不上。</p><footer>—— 据 Chaudhuri and Narasayya 自动索引选择；Selinger 访问路径；谓词下推主干课的物理侧</footer></div><p><a href="/cs/learned-optimizer">上一课</a>把反馈收成估计插件。本课不训练模型。缺口是物理设计与改写的交界：主干 <a href="/cs/covering-index">覆盖索引</a>、<a href="/cs/predicate-pushdown">谓词下推</a> 已有概念；进阶要把<strong>选哪些索引</strong>与<strong>谓词能否贴到索引扫描</strong>一次讲清，否则优化器单元只在既定索引上搜。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索引太多：更新、空间、优化时间（每个索引都是访问路径候选）。太少：全表扫描。自动选择把工作负载当输入，在候选索引集上搜索收益（估计代价下降）减维护成本。缺口还包括下推：<code>WHERE</code> 里的函数包住列（<code>f(col)=1</code>）会挡住索引匹配；外连接、窗口、分组是防火墙，谓词不能穿越。</p><p>下推是逻辑改写；索引匹配是物理。两者失败症状都是「扫太多行」，诊断要分开。</p><p><span class="marginnote">术语翻译：「sargable」可以读成「能用索引的」（Search ARGument ABLE）——谓词的形状要让索引键的有序性直接派上用场。<code>col = 5</code>、<code>col BETWEEN 1 AND 9</code> 是；<code>f(col) = 5</code> 不是，因为索引里存的是 <code>col</code> 原值，算过 <code>f</code> 的值在树里没有位置。</span></p><p><span class="marginnote">Chaudhuri and Narasayya 的 AutoAdmin 索引选择。下推合法性仍由代数与 NULL 决定，本课不重推三值。INCLUDE 列服务覆盖，属于设计空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>候选：查询里等值、范围、连接键、<code>ORDER BY</code>/<code>GROUP BY</code> 前缀。搜索：贪心加索引、或整数规划近似。约束：每表索引个数、写放大预算。条件下推：把选择算子推到扫描与连接之下，直到防火墙；再看残留谓词能否当索引条件（sargable）。</p><p>部分索引、表达式索引：把不可 sargable 的计算预物化进索引键。这是设计，不是运行时下推。</p>',11)),(o(),l(d,null,{default:e(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WL%5B%22%E5%B7%A5%E4%BD%9C%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E7%B4%A2%E5%BC%95%22%5D%0A%20%20CAND%20--%3E%20PICK%5B%22%E6%94%B6%E7%9B%8A%E5%87%8F%E7%BB%B4%E6%8A%A4%22%5D%0A%20%20Q%5B%22%E9%80%BB%E8%BE%91%E6%A0%91%22%5D%20--%3E%20PUSH%5B%22%E6%9D%A1%E4%BB%B6%E4%B8%8B%E6%8E%A8%22%5D%0A%20%20PUSH%20--%3E%20SARG%5B%22%E7%B4%A2%E5%BC%95%E5%8C%B9%E9%85%8D%20%2F%20%E6%AE%8B%E7%95%99%E8%BF%87%E6%BB%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"优化器在 DP 单表步枚举：堆扫、各匹配索引、位图交（后课位图索引）。选择结果依赖统计。错误下推改变指称，比选错索引更严重——先合法后代价。",-1)),a[5]||(a[5]=r("p",null,"一个不可 sargable 的谓词如何被救回来：",-1)),(o(),l(d,null,{default:e(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%B0%93%E8%AF%8D%EF%BC%9Ayear(birthday)%20%3D%201990%22%5D%20--%3E%20Q%7B%22%E5%87%BD%E6%95%B0%E5%8C%85%E4%BD%8F%E4%BA%86%E5%88%97%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20NO%5B%22%E7%B4%A2%E5%BC%95%E9%94%AE%E6%9C%89%E5%BA%8F%E4%BD%86%E5%AF%B9%E4%B8%8D%E4%B8%8A%E5%8F%B7%22%5D%0A%20%20NO%20--%3E%20RW%5B%22%E6%94%B9%E5%86%99%E6%88%90%E8%8C%83%E5%9B%B4%EF%BC%9Abirthday%20%E8%90%BD%E5%9C%A8%201990%20%E5%B9%B4%E5%86%85%22%5D%0A%20%20RW%20--%3E%20OK%5B%22%E5%8F%AF%20sargable%EF%BC%9A%E8%B5%B0%E7%B4%A2%E5%BC%95%E8%8C%83%E5%9B%B4%E6%89%AB%E6%8F%8F%22%5D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20OK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数字实例：写放大预算的含义——表上有 5 个二级索引时，每 INSERT 一行约等于写 6 棵树（1 聚簇 + 5 二级）。给写多读少的表随手加索引，读没快多少，写入吞吐先掉一半是常见结局。</span></p><p><span class="marginnote">常见误区：初学者容易以为「建了索引优化器就该用」。优化器按统计信息估代价：若谓词选择性很差（比如按「性别」列过滤一半的行），回表取一半数据比直接全表顺序扫更慢，优化器会理直气壮地不用这个索引。</span></p><p>物化视图是「预计算查询」的索引亲戚；刷新下一课。本课索引是访问路径，不是另一张用户表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲物化视图增量维护代数。也不把 DBA 提示当选择算法。计划提示下一课之后。分区裁剪是表分区课的下推亲戚，存储进阶再写。</p><p>后课默认：先让谓词 sargable 并下推，再谈加索引；自动选择有写放大预算。物化视图刷新是另一份维护合同。</p><p>没有下推，最宽的覆盖索引也只是又一次全扫叶子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>索引选择用工作负载权衡读收益与写成本。</li><li>条件下推与 sargable 决定索引能否被匹配。</li><li>物化视图刷新下一课：预计算查询的维护。</li><li>出处：Chaudhuri and Narasayya；Selinger；Ramakrishnan and Gehrke。</li></ul>',9))])}const g=i(c,[["render",A]]);export{b as __pageData,g as default};
